-- State transitions declared for SalesOrder (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION selling.sales_orders_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'cancelled'), ('draft', 'to_deliver_and_bill'), ('to_bill', 'cancelled'), ('to_bill', 'closed'), ('to_bill', 'completed'), ('to_deliver', 'cancelled'), ('to_deliver', 'completed'), ('to_deliver_and_bill', 'cancelled'), ('to_deliver_and_bill', 'to_bill'), ('to_deliver_and_bill', 'to_deliver'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: sales_orders.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS sales_orders_status_transition_check ON selling.sales_orders;
CREATE TRIGGER sales_orders_status_transition_check
    BEFORE UPDATE OF "status" ON selling.sales_orders
    FOR EACH ROW EXECUTE FUNCTION selling.sales_orders_status_transition_check();
